'use strict';
// Presentation only: existing owner-scoped stores and save paths remain authoritative.
let companionTab='home';
const companionButton=(label,action,detail='',symbol='review')=>`<button class="companion-card" data-companion="${action}">${journalIcon(symbol)}<span><strong>${label}</strong><small>${detail}</small></span><b>›</b></button>`;
const companionOldNav=renderNav;
renderNav=function(){companionOldNav();if(!state.hubOnboardingCompleted)return;const selected=page==='home'||['learn','progress'].includes(page)?'home':page==='profile'||['settings','access','privacy'].includes(page)?'profile':page==='career'?companionTab:'plans';for(const id of ['mobileNav','desktopNav']){const el=document.getElementById(id);if(el)el.innerHTML=[['home','Home','home'],['docs','Docs','learn'],['quick','＋','plus'],['plans','Plans','review'],['profile','Profile','profile']].map(([key,label,symbol])=>`<button data-companion="${key}" class="${selected===key?'active':''} ${key==='quick'?'companion-plus':''}" aria-label="${key==='quick'?'Quick actions':label}" ${selected===key?'aria-current="page"':''}>${key==='quick'?'<b>＋</b>':icon(symbol)}<span>${key==='quick'?'Add':label}</span></button>`).join('')}};
learningToday=function(){const s=learningJournalInsights(),p=learningStats();app.innerHTML=`<div class="companion-toolbar"><button data-nav="progress">${journalIcon('sparkles')} Milestones</button><div><button data-companion="reminders" aria-label="Reminders">${journalIcon('reminder')}</button><button data-nav="settings" aria-label="Settings">⚙</button></div></div><section class="companion-hero"><small>${new Date().toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric'})}</small><h1>Hello, ${esc(state.profile.name||'seafarer')}.</h1><div><p>Your next chapter<br>starts with today.<small>A little preparation. A little progress.</small></p><img src="assets/toolbox-spanner.png" alt="Toolbox companion"></div></section><div class="companion-section"><h2>Your progress</h2><button data-nav="progress">View all →</button></div><div class="companion-stats"><button data-nav="learn"><b>${s.entries}</b><span>Journal entries</span></button><button data-nav="progress"><b>${p.answered}</b><span>Questions practised</span></button><button data-nav="progress"><b>${s.days}</b><span>Days journaled</span></button></div><div class="companion-section"><h2>Make space for yourself</h2></div>${companionButton('What’s on your mind?','journal','Write a thought or keep a lesson from your watch.','write')}${companionButton('Today & upcoming','schedule','Your appointments, plans and important dates.','calendar')}<div class="companion-section"><h2>Keep moving forward</h2></div>${companionButton('Continue learning','study','Study, practise and prepare for your next rank.','review')}${companionButton('My journal','library',`${s.words.toLocaleString()} words kept · Browse your entries`,'words')}`};
const companionCareerHome=careerHome;
careerHome=function(){if(companionTab!=='docs'&&companionTab!=='plans'){companionCareerHome();return}if(companionTab==='plans'){app.innerHTML=`<header class="companion-heading"><small>YOUR NEXT CHAPTER</small><h1>Plans</h1><p>Prepare for sea. Make room to grow.</p></header><h2>Prepare to sail</h2>${companionButton('Schedules & checklists','schedule','Appointments, renewals and things to prepare.','calendar')}${companionButton('Sea service','sea','Keep your ships and experience together.','topic')}<h2>Develop your career</h2>${companionButton('Study & exams','study','Your existing study library and practice exams.','review')}${companionButton('Communication practice','speaking','28 days of articulation and presence.','words')}<h2>Career tools</h2>${companionButton('Generate CV','cv','Preview, print or download your PDF.','photo')}${companionButton('Career profile & backup','career','Manage details, education and private backups.','topic')}`;return}app.innerHTML=`<header class="companion-heading"><small>READY WHEN YOU NEED THEM</small><h1>Docs</h1><p>Your records. Always within reach.</p></header><label class="search">${icon('search')}<input id="companionDocSearch" type="search" placeholder="Search your documents" aria-label="Search documents"></label><div class="career-actions"><button class="btn" data-career-new="certificates">Add certificate</button><button class="btn quiet" data-career-list="documents">IDs & travel documents</button></div><div id="companionDocs"></div>`;companionDocuments('');document.getElementById('companionDocSearch').oninput=e=>companionDocuments(e.target.value)};
function companionDocuments(query){const rows=['documents','certificates','vaccinations'].flatMap(section=>careerRows(section).map(row=>({section,row}))).filter(x=>(x.row.title+' '+x.row.number+' '+x.row.issuer).toLowerCase().includes(query.toLowerCase()));document.getElementById('companionDocs').innerHTML=rows.map(({section,row})=>`<article class="card"><small>${esc(careerSchemas[section].title)}</small><h2>${esc(row.title||'Untitled record')}</h2>${careerExpiryTag(row)}<p>${row.expires?'Expires '+esc(careerDate(row.expires)):'No expiry date recorded'}</p><button class="btn quiet" data-companion-record="${esc(row.id)}" data-section="${section}">View document →</button></article>`).join('')||'<section class="card"><h2>Your documents belong here</h2><p>Add a record or try another search.</p></section>'}
function companionQuick(){let d=document.getElementById('companionQuick');if(!d){d=document.createElement('dialog');d.id='companionQuick';document.body.append(d)}d.innerHTML=`<div class="companion-section"><h2>Make your next move</h2><button data-companion="close" aria-label="Close quick actions">×</button></div>${companionButton('Write a journal','journal','','write')}${companionButton('Add document','addDocument','','photo')}${companionButton('Add reminder or task','addPlan','','calendar')}`;d.showModal()}
function companionGo(action){document.getElementById('companionQuick')?.close();if(action==='close')return;if(action==='quick'){companionQuick();return}if(action==='home'||action==='profile'){companionTab=action;nav(action);return}if(action==='docs'||action==='plans'){companionTab=action;careerGo();return}if(action==='journal'){document.querySelector('[data-learning="new"]')?.click();if(page!=='learn'){nav('learn');document.querySelector('[data-learning="new"]')?.click()}return}if(action==='library'){nav('learn');return}if(action==='study'){nav('review');return}if(action==='speaking'){void lhOpenSpeaking();return}companionTab='plans';if(action==='career'){companionTab='profile';careerGo();return}if(action==='cv'){careerGo('cv');return}if(action==='sea'){careerList('sea');return}if(['schedule','reminders','addPlan'].includes(action)){careerList('plans');if(action==='addPlan')document.querySelector('[data-career-new="plans"]')?.click();return}if(action==='addDocument'){companionTab='docs';careerList('documents');document.querySelector('[data-career-new="documents"]')?.click()}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-companion], [data-companion-record]');if(!b)return;e.preventDefault();if(b.dataset.companionRecord){careerSection=b.dataset.section;careerEditId=b.dataset.companionRecord;careerGo('files')}else companionGo(b.dataset.companion)});
hubQuickGuides.home=['Home',['See your journal and learning progress.','Use Plans for preparation and learning, Docs for your private records.','The centre Add button opens quick actions.']];
render();
// Keep Home quiet; utilities live with the person's preferences.
const companionHomeBase=learningToday;
learningToday=function(){companionHomeBase();app.querySelector('.companion-toolbar')?.remove();app.querySelector('.companion-hero')?.insertAdjacentHTML('afterend',companionCalendar());if(!careerData&&!careerLoading&&!careerError&&careerReady())void careerLoad()};
function companionCalendar(){const days=learningWeekDays(0),plans=careerData&&careerOwner===careerAccount()?careerRows('plans').filter(r=>!r.done):[];const upcoming=plans.filter(r=>r.due&&r.due>=learningDate()).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,2);return `<section class="companion-calendar" aria-label="This week's schedule"><div class="companion-section"><h2>This week</h2><button data-companion="schedule">Schedule →</button></div><div class="companion-week">${days.map(d=>`<button data-companion="schedule" class="${d.key===learningDate()?'today':''}" aria-label="${d.key}, ${plans.filter(p=>p.due===d.key).length} plans"><small>${d.day.slice(0,1)}</small><b>${d.number}</b><i>${plans.some(p=>p.due===d.key)?'•':''}</i></button>`).join('')}</div><div class="companion-agenda">${upcoming.map(p=>`<p>${esc(careerDate(p.due))} · ${esc(p.title)}</p>`).join('')||'No upcoming plans. Add a date when you need one.'}</div></section>`}
const companionProfileBase=profile;
profile=function(){companionProfileBase();app.insertAdjacentHTML('beforeend',`<section class="card"><h2>Your preferences</h2>${companionButton('Milestones & progress','milestones','','sparkles')}${companionButton('Reminders','reminders','','reminder')}${companionButton('Settings','settings','','topic')}</section>`)};
const companionGoBase=companionGo;
companionGo=async function(action){if(action==='milestones'||action==='settings'){document.getElementById('companionQuick')?.close();nav(action==='milestones'?'progress':'settings');return}if(action==='addPlan'||action==='addDocument'){document.getElementById('companionQuick')?.close();const owner=careerAccount();if(!careerData){await careerLoad();if(owner!==careerAccount()||!careerData)return} }companionGoBase(action)};
const companionQuickBase=companionQuick;
companionQuick=function(){companionQuickBase();document.getElementById('companionQuick').insertAdjacentHTML('beforeend',companionButton('Start studying or an exam','study','','review'))};
const companionRenderBase=render;
render=function(){companionRenderBase();if(page==='home'&&state.hubOnboardingCompleted)document.getElementById('sectionName').textContent='Home'};
render();
